package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry.LF_DIR;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TarArchiveEntry_isDirectory_TriageGen2Test {

    /**
     * Helper to set the private 'file' field via reflection since 
     * it is used in the logic but not directly settable via public API.
     */
    private void setFileField(TarArchiveEntry entry, File file) throws Exception {
        Field field = TarArchiveEntry.class.getDeclaredField("file");
        field.setAccessible(true);
        field.set(entry, file);
    }

    /**
     * Helper to set the private 'linkFlag' field via reflection.
     */
    private void setLinkFlagField(TarArchiveEntry entry, byte linkFlag) throws Exception {
        Field field = TarArchiveEntry.class.getDeclaredField("linkFlag");
        field.setAccessible(true);
        field.set(entry, linkFlag);
    }

    @Test
    public void testIsDirectory_FileIsDirectory() throws Exception {
        // Mocking behavior: if file != null, return file.isDirectory()
        // We use a real File object that points to a directory if possible, 
        // or we rely on the logic branch.
        File dir = new File(System.getProperty("java.io.tmpdir"));
        TarArchiveEntry entry = new TarArchiveEntry("testDir");
        setFileField(entry, dir);

        assertTrue("Should return true when file.isDirectory() is true", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_FileIsNotDirectory() throws Exception {
        // Using a non-existent file or a file that is not a directory
        File file = new File("non_existent_file_12345.txt");
        TarArchiveEntry entry = new TarArchiveEntry("testFile");
        setFileField(entry, file);

        assertFalse("Should return false when file.isDirectory() is false", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_LinkFlagIsLFDir() throws Exception {
        // file is null, linkFlag is LF_DIR
        TarArchiveEntry entry = new TarArchiveEntry("someName");
        setLinkFlagField(entry, LF_DIR);

        assertTrue("Should return true when linkFlag is LF_DIR", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_NameEndsWithSlash() throws Exception {
        // file is null, linkFlag is not LF_DIR, name ends with '/'
        TarArchiveEntry entry = new TarArchiveEntry("folder/");
        setLinkFlagField(entry, (byte) 0); // Assuming 0 is not LF_DIR

        assertTrue("Should return true when name ends with '/'", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_AllConditionsFalse() throws Exception {
        // file is null, linkFlag is not LF_DIR, name does not end with '/'
        TarArchiveEntry entry = new TarArchiveEntry("regularFile");
        setLinkFlagField(entry, (byte) 0);

        assertFalse("Should return false when all conditions are false", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_NullFileAndLinkFlagDirButNameEndsWithSlash() throws Exception {
        // Testing branch priority: if linkFlag == LF_DIR, it returns true before checking name
        TarArchiveEntry entry = new TarArchiveEntry("folder/");
        setLinkFlagField(entry, LF_DIR);

        assertTrue("Should return true via linkFlag check", entry.isDirectory());
    }
}
